import{_ as t,o as s,c as i,a4 as a}from"./chunks/framework.BE47AOxC.js";const m=JSON.parse('{"title":"ADR-0003 — Schéma utilisateurs : staff_users / end_users","description":"Extrait de docs/adr/0003-schema-utilisateurs-staff-end.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0003 — Schéma utilisateurs : staff_users / end_users","description":"Extrait de docs/adr/0003-schema-utilisateurs-staff-end.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0003-schema-utilisateurs-staff-end.md","filePath":"developpeurs/adr/0003-schema-utilisateurs-staff-end.md"}'),n={name:"developpeurs/adr/0003-schema-utilisateurs-staff-end.md"};function o(r,e,d,u,c,l){return s(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="adr-0003--schéma-utilisateurs--staff_users--end_users" tabindex="-1">ADR-0003 — Schéma utilisateurs : <code>staff_users</code> / <code>end_users</code> <a class="header-anchor" href="#adr-0003--schéma-utilisateurs--staff_users--end_users" aria-label="Permalink to &quot;ADR-0003 — Schéma utilisateurs : `staff_users` / `end_users` {#adr-0003--schéma-utilisateurs--staff_users--end_users}&quot;">​</a></h1><p><strong>Date :</strong> 19 août 2026 <strong>Statut :</strong> Accepté <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> CDC_CMS_AI_Native_v1.1 §8.1, §17 point ouvert #3 ; plan d&#39;action agile §3.1.bis (analyse Merise)</p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p>Le CDC identifie deux populations d&#39;utilisateurs distinctes, absentes de la v1.0 qui ne traitait que les utilisateurs du back-office : les <strong>utilisateurs back-office</strong> (Admin, Editor, Author, Reviewer, Translator — login CMS, MFA, SSO/SAML) et les <strong>utilisateurs front/usagers</strong> (compte de service, extranet — login local, OIDC type FranceConnect). Le CDC recommande deux entités distinctes, <code>staff_users</code> et <code>end_users</code>, en signalant que les mélanger dans une seule table « expose la surface d&#39;administration à une population non maîtrisée, et complique l&#39;isolation multi-tenant ».</p><p>Décision qualifiée par le CDC de « structurante, très coûteuse à revenir après coup ».</p><h2 id="analyse-méthode-merise--mcd" tabindex="-1">Analyse (méthode Merise — MCD) <a class="header-anchor" href="#analyse-méthode-merise--mcd" aria-label="Permalink to &quot;Analyse (méthode Merise — MCD) {#analyse-méthode-merise--mcd}&quot;">​</a></h2><p><strong>Entités candidates et leurs propriétés propres :</strong></p><table tabindex="0"><thead><tr><th></th><th><code>UTILISATEUR_STAFF</code></th><th><code>UTILISATEUR_FINAL</code></th></tr></thead><tbody><tr><td>Authentification</td><td>login CMS, MFA, SSO/SAML</td><td>login local, OIDC (FranceConnect)</td></tr><tr><td>Attribut structurant</td><td><code>role</code> (Admin/Editor/Author/Reviewer/Translator)</td><td><code>consentement_rgpd</code>, <code>date_derniere_activite</code></td></tr><tr><td>Règle de cycle de vie</td><td>aucune purge automatique</td><td>purge à 24 h (inscription non confirmée), relances 20/24 mois, suppression physique à 24 mois</td></tr><tr><td>Associations</td><td>RÉDIGE→Contenu, POSSÈDE→Permission, APPARTIENT_A→Organisation</td><td>SOUMET→Demande SVE, ABONNE_A→Flux, PROPOSE→Contribution, POSSÈDE→Favori</td></tr></tbody></table><p><strong>Test de l&#39;entité unique.</strong> Pour fusionner en une seule entité <code>UTILISATEUR</code>, tous les attributs devraient s&#39;appliquer à toutes les occurrences (principe d&#39;homogénéité de l&#39;entité en Merise). Ce n&#39;est pas le cas : <code>role</code> RBAC n&#39;a pas de sens pour un usager ; <code>date_derniere_activite</code> et les règles de purge n&#39;ont pas de sens pour un agent du back-office. Une fusion imposerait un discriminant <code>type</code> avec des colonnes conditionnellement nulles — signe classique qu&#39;il s&#39;agit de deux sous-types, pas d&#39;une entité plate.</p><p><strong>Test du supertype commun <code>PERSONNE</code>.</strong> Légitime seulement si une association a besoin d&#39;interroger indifféremment les deux populations. Aucune exigence du CDC ne le demande — au contraire, le CDC exige explicitement de pouvoir les isoler (surface d&#39;attaque admin, isolation multi-organisation, politiques de rétention distinctes). Un supertype commun n&#39;est donc pas justifié.</p><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><p>Deux entités indépendantes, donc deux tables physiques distinctes : <strong><code>staff_users</code></strong> et <strong><code>end_users</code></strong>, chacune avec ses propres clés étrangères vers ce qu&#39;elle manipule (<code>staff_users</code> → sites/organisations/permissions ; <code>end_users</code> → demandes SVE, abonnements, contributions, favoris). Aucune table ou entité <code>users</code> commune ne sera introduite pour les regrouper.</p><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Pourquoi écartée</th></tr></thead><tbody><tr><td><strong>Une seule table <code>users</code> avec un discriminant de rôle</strong></td><td>Plus simple à court terme (un seul modèle d&#39;authentification), mais échoue au test de l&#39;entité unique (§ ci-dessus) et expose la surface d&#39;administration à la population usager — risque explicitement signalé par le CDC.</td></tr></tbody></table><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives</strong></p><ul><li>Isolation de sécurité claire dès le schéma : aucune requête ne peut accidentellement mélanger les deux populations.</li><li>Politiques de rétention indépendantes et paramétrables par organisation sans conflit de modèle (24 h / 20 mois / 24 mois pour <code>end_users</code>, aucune purge automatique pour <code>staff_users</code>).</li><li>Le RBAC (permissions, rôles) reste scopé à <code>staff_users</code>, ce qui simplifie l&#39;ACL par arbre de pages (Epic E6, cf. §8.4 du CDC).</li></ul><p><strong>Négatives</strong></p><ul><li>Deux systèmes d&#39;authentification à maintenir (session/JWT pour <code>staff_users</code>, OIDC pour <code>end_users</code>) plutôt qu&#39;un seul.</li><li>Si un besoin réel émerge plus tard de faire agir un même individu physique dans les deux rôles (ex. un agent qui est aussi usager de son propre site), il faudra un mécanisme de liaison explicite entre les deux tables plutôt qu&#39;une identité unique — ce cas n&#39;est pas couvert par le CDC et n&#39;est pas anticipé dans ce schéma.</li></ul><h2 id="actions-liées" tabindex="-1">Actions liées <a class="header-anchor" href="#actions-liées" aria-label="Permalink to &quot;Actions liées {#actions-liées}&quot;">​</a></h2><ul><li>[x] Poser <code>staff_users</code> et <code>end_users</code> comme deux tables dès la première migration touchant l&#39;authentification — fait par la migration <code>0007</code> (Epic E6). Aucune migration antérieure ne touchait à l&#39;authentification : <code>personal_data_access_logs.actor_id</code> (E5) et <code>content_lifecycle_events.actor_id</code> (E4) ont volontairement été posées <strong>sans clé étrangère</strong>, en attendant cette décision.</li><li>[x] Ne pas introduire de table <code>users</code> générique, même temporairement — vérifié mécaniquement par <code>test_deux_populations_deux_tables_jamais_fusionnees</code> (<code>apps/api/tests/test_rbac.py</code>), qui inspecte les métadonnées SQLAlchemy réelles : absence de table <code>users</code>, absence de classe mère commune, absence de clé étrangère croisée entre les deux populations.</li><li>[x] Séparer aussi les <strong>fournisseurs d&#39;identité</strong> : <code>app/rbac/providers.py</code> tient deux registres distincts (SAML pour <code>staff_users</code>, OIDC pour <code>end_users</code>) et refuse d&#39;enregistrer un fournisseur dans le registre de l&#39;autre population — sans quoi la table <code>users</code> écartée ici serait réintroduite par le côté authentification.</li><li>[x] Epic E12 : cycle de vie du compte usager (inscription, confirmation, OIDC/FranceConnect, purge 24 h / 20 mois / 24 mois, export). L&#39;Epic E6 n&#39;avait posé d&#39;<code>end_users</code> que le squelette nécessaire à l&#39;ACL par arbre de pages ; la migration <code>0012</code> y ajoute l&#39;authentification locale, la confirmation d&#39;inscription et les dates du cycle de vie RGPD. Les durées sont des <strong>valeurs par défaut paramétrables par organisation</strong> (<code>organizations.settings[&quot;end_users&quot;]</code>, <code>app/end_users/policy.py</code>), jamais des constantes.</li><li>[x] Étendre la séparation aux <strong>sessions</strong> : <code>staff_sessions</code> et <code>end_user_sessions</code> sont deux tables distinctes (migration <code>0012</code>). Une table de jetons commune aurait porté une colonne « de quelle population vient ce porteur ? », c&#39;est-à-dire le discriminant de la table <code>users</code> écartée ici, réintroduit par le côté authentification. Vérifié mécaniquement par <code>test_deux_populations_deux_tables_jusqu_aux_sessions</code> (<code>apps/api/tests/test_end_users.py</code>), qui contrôle qu&#39;aucun chemin de clé étrangère ne relie une table de session d&#39;une population à l&#39;autre.</li><li>[x] Séparer aussi le <strong>code</strong> : <code>app/end_users/</code> (inscription, sessions usager, OIDC/FranceConnect, espace personnel, rétention) est un paquet distinct de <code>app/rbac/</code> (rôles, permissions, sessions d&#39;agent, second facteur, SSO/SAML). Seules des primitives sans population sont partagées — le hachage de mot de passe et les sujets d&#39;accès de l&#39;ACL. Vérifié par <code>test_oidc_et_saml_ne_partagent_aucun_code</code>, qui inspecte le vocabulaire <strong>exécuté</strong> des deux paquets.</li></ul>',21)])])}const f=t(n,[["render",o]]);export{m as __pageData,f as default};
